StructuredBuffer<uint> Source : register(t0);
RWStructuredBuffer<uint> Output : register(u0);
RWStructuredBuffer<uint> Readback : register(u1);
cbuffer Parameters : register(b0) { uint Count; };

uint mixWord(uint value) {
    value ^= value >> 16u;
    value *= 0x7feb352du;
    return value ^ (value >> 15u);
}

[numthreads(64, 1, 1)]
void main(uint3 id : SV_DispatchThreadID) {
    uint index = id.x;
    if (index >= Count) return;
    bool active = index < Count && Source[index] != 0u;
    uint word = active ? mixWord(Source[index]) : Source[index];
    Output[index] = word;
    Readback[index] = Output[index];
}
